INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_opportunity-annual-education-call-2026','opportunity-annual-education-call-2026',1,'{"id":"opportunity-annual-education-call-2026","slug":"annual-education-call-2026-2027","title":"INGENIUM Annual Education Call 2026/2027","type":"opportunity","subtype":"Education co-creation call","studentSummary":"A call for staff and programme coordinators to create joint learning across the ten universities.","fullDescription":"The current announcement covers nine categories: joint programmes; Pathways and windows; doctoral collaboration; BIPs; microcredentials and micromodules; collaborative teaching; teaching innovation; Staff Academy training; and Course Catalogue contributions. Academic staff and programme directors can lead, while technical staff, students and external stakeholders can co-create. Older official summaries contain different deadlines, so the record remains verification required.","status":"Open now","universityIds":["university-mtu","university-hka","university-xamk","university-hs","university-uoc","university-mus","university-uniovi","university-urn","university-uda","university-tuiasi"],"themes":["Joint education","Teaching innovation","European campus"],"academicLevel":"Staff and programme coordinators","applicationOpenDate":"2026-09-14","eligibility":"Academic staff and programme directors across all ten partners may lead; technical staff, students and external stakeholders may co-create","actionLabel":"Open the live annual call","officialUrl":"https://ingenium-university.eu/iec-faculty/ingenium-annual-education-call-2026-2027/","sourceId":"fc29-annual-education-call","confidence":"High","sourceIds":["education-call-2026","fc29-annual-education-call"],"lastVerified":"2026-10-01","dataClassification":"verified","availability":"Open on 1 October 2026: fast-track deadline 16 October; general expression of interest 13 November; final deadline 18 December 2026","applicationDeadline":"2026-12-18","startDate":"2026-09-14","endDate":"2027-07-31"}','Imported from the verified INGENIUM+ v1.5 dataset','fc29-annual-education-call');
