INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_project-ingenium-ed','project-ingenium-ed',1,'{"id":"project-ingenium-ed","slug":"ingenium-ed","title":"INGENIUM-ED","shortTitle":"INGENIUM-ED","type":"project","subtype":"European Degree Label alignment project","studentSummary":"A 36-month project coordinating alliance joint programmes with the emerging Joint European Degree Label criteria.","status":"Ongoing","availability":"Funded 36-month European Degree exploratory action running through December 2029","universityIds":["university-uniovi","university-mus","university-uoc","university-hka","university-xamk","university-uda","university-hs","university-mtu","university-urn","university-tuiasi"],"hostUniversityId":"university-uniovi","themes":["European Degree","Joint programmes","Student support"],"endDate":"2029-12-31","funding":"Funded project; amount not stated on the official partner page","whyItMatters":"Targets adapted and newly designed joint programmes and support for at least 200 students, including underrepresented learners.","actionLabel":"Read the official project announcement","officialUrl":"https://www.tuiasi.ro/news/ingenium-ed-the-ingenium-alliance-is-preparing-the-new-generation-of-joint-european-study-programmes/?lang=en","sourceId":"fc-ingenium-ed-2026","confidence":"High","featured":true,"lastVerified":"2026-09-29","dataClassification":"verified","sourceIds":["fc-ingenium-ed-2026"],"fullDescription":"All ten partners are adapting existing joint programmes and developing CBPT, SMAC², MIDAS and the Bachelor in Innovation and Entrepreneurship against European Degree Label criteria. The project also pilots a common EGTC structure and targets support for at least 200 students, including underrepresented learners."}','Imported from the verified INGENIUM+ v1.5 dataset','fc-ingenium-ed-2026');
