INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_opportunity-ingenium-ambassadors-2026','opportunity-ingenium-ambassadors-2026',1,'{"id":"opportunity-ingenium-ambassadors-2026","slug":"ingenium-ambassadors-call-2026-2027","title":"INGENIUM Ambassadors Call 2026/2027","type":"opportunity","subtype":"Student communication-project call","studentSummary":"Students can propose communication projects that bring the alliance closer to their peers and include a funded exchange visit to another partner university.","fullDescription":"Projects are led by one student or a two-student team at the same partner university. The seven-month period runs from 1 November 2026 to 31 May 2027, followed by a final report and closing piece by the end of June.","status":"Opens soon","availability":"Applications open 1 October and close 18 October 2026 at 23:59 CET","universityIds":["university-mtu","university-hka","university-xamk","university-hs","university-uoc","university-mus","university-uniovi","university-urn","university-uda","university-tuiasi"],"themes":["Student voice","Communication","Mobility"],"academicLevel":"Bachelor, Master or PhD","startDate":"2026-11-01","endDate":"2027-05-31","applicationOpenDate":"2026-10-01","applicationDeadline":"2026-10-18","eligibility":"One student or a team of two at the same participating university, with uninterrupted student status through the project period","funding":"Exchange visit funded up to €1,000 per team member","capacity":"At least one project per participating university, subject to local-office capacity","actionLabel":"Prepare an Ambassadors proposal","officialUrl":"https://ingenium-university.eu/ingenium-ambassadors-call-2026-2027/","sourceId":"fc-full-ambassadors","featured":true,"lastVerified":"2026-09-29","confidence":"High","dataClassification":"verified","sourceIds":["fc-full-ambassadors"]}','Imported from the verified INGENIUM+ v1.5 dataset','fc-full-ambassadors');
