INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_course-using-wellbeing-skills-to-promote-studying-ability','course-using-wellbeing-skills-to-promote-studying-ability',1,'{"id":"course-using-wellbeing-skills-to-promote-studying-ability","slug":"using-wellbeing-skills-to-promote-studying-ability","title":"Using Wellbeing Skills to Promote Studying Ability","type":"course","subtype":"INGENIUM catalogue course","studentSummary":"The aim of this course is to promote students'' study ability and wellbeing. The course offers tools to support learning, coping and wellbeing. In this course, students study strongly themselves, reflecting on their own learning and well-being. The course contains learning material in many differe...","fullDescription":"The aim of this course is to promote students'' study ability and wellbeing. The course offers tools to support learning, coping and wellbeing. In this course, students study strongly themselves, reflecting on their own learning and well-being. The course contains learning material in many different formats (e.g. texts, videos, podcasts). This course is completed independently online on Xamk Learn digital learning environment. The participant acquires Xamk user credentials before the course begins by identifying electronically with a passport or a biometric EU/EEA identity card, using Candour ID mobile application.Once the enrolment period has ended, you will receive Candour ID instructions by email (from ). Enrollment for this course is open till 27.09.2026.","status":"Access unverified","availability":"Public catalogue detail page; current enrolment and delivery dates require confirmation","universityIds":[],"themes":["Wellbeing","Study skills"],"actionLabel":"Open the official course page","officialUrl":"https://ingenium-university.eu/courses/using-wellbeing-skills-to-promote-studying-ability/","sourceId":"fc-cat-using-wellbeing-skills-to-promote-